//! # akatsuki-tokens
//!
//! Akatsuki's design tokens ("crimson dawn minimalism") as Rust constants for the GPUI desktop app.
//!
//! `packages/tokens/tokens.json` is the single source (BRIEF "Design theme"). Its build script
//! (`pnpm --filter @akatsuki/tokens build`) writes [`generated`] — never edit that file by hand.
//! This shell adds the few helpers every renderer needs on top of the generated constants.

// Generated by packages/tokens/scripts/build.ts; rustfmt is skipped so `pnpm tokens:build` and
// `cargo fmt --check` never disagree about its layout (the generator output is the canonical form).
#[rustfmt::skip]
#[allow(missing_docs, clippy::all)]
mod generated;

pub use generated::*;

/// Light or dark appearance.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Appearance {
    /// Light: crimson `#C1272D` on white.
    Light,
    /// Dark: deep crimson `#800000` on `#0A0A0A`.
    Dark,
}

impl Appearance {
    /// The palette for this appearance.
    pub const fn palette(self) -> Palette {
        match self {
            Appearance::Light => LIGHT,
            Appearance::Dark => DARK,
        }
    }
}

impl Rgb {
    /// Channels as floats in `[0, 1]`.
    pub fn to_f32(self) -> [f32; 3] {
        [f32::from(self.r) / 255.0, f32::from(self.g) / 255.0, f32::from(self.b) / 255.0]
    }

    /// Alpha-blends this colour over `background` (for borders and muted text on opaque surfaces).
    pub fn over(self, background: Rgb, alpha: f32) -> Rgb {
        let a = alpha.clamp(0.0, 1.0);
        let mix = |f: u8, b: u8| (f32::from(f) * a + f32::from(b) * (1.0 - a)).round() as u8;
        Rgb { r: mix(self.r, background.r), g: mix(self.g, background.g), b: mix(self.b, background.b) }
    }
}

impl TextStyle {
    /// The font family name to request from the text system.
    pub const fn family(&self) -> &'static str {
        match self.font {
            FontRole::Serif => font::serif::FAMILY,
            FontRole::Sans => font::sans::FAMILY,
            FontRole::Mono => font::mono::FAMILY,
        }
    }

    /// Size for a window of `width` px (`size_wide` applies from 768 px).
    pub fn size_for_width(&self, width: f32) -> f32 {
        match self.size_wide {
            Some(wide) if width >= 768.0 => wide,
            _ => self.size,
        }
    }

    /// Letter spacing in px.
    pub fn tracking_px(&self, size: f32) -> f32 {
        self.tracking_em * size
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn brief_palette() {
        assert_eq!(LIGHT.accent.hex(), 0xC1272D);
        assert_eq!(LIGHT.background.hex(), 0xFFFFFF);
        assert_eq!(LIGHT.foreground.hex(), 0x171717);
        assert_eq!(DARK.accent.hex(), 0x800000);
        assert_eq!(DARK.background.hex(), 0x0A0A0A);
        assert_eq!(DARK.foreground.hex(), 0xEDEDED);
        assert_eq!(Appearance::Dark.palette(), DARK);
    }

    #[test]
    fn opacity_scales_match_brief() {
        assert_eq!(opacity::foreground::SECONDARY, 0.8);
        assert_eq!(opacity::foreground::BORDER, 0.2);
        assert_eq!(opacity::accent::WASH, 0.08);
    }

    #[test]
    fn fonts_and_styles() {
        assert_eq!(font::serif::FAMILY, "Instrument Serif");
        assert_eq!(font::serif::WEIGHTS, &[400]);
        assert_eq!(text::brand::DISPLAY.family(), "Instrument Serif");
        assert_eq!(text::app::BODY.family(), "Geist");
        assert_eq!(text::brand::DISPLAY.size_for_width(1200.0), 120.0);
        assert_eq!(text::brand::DISPLAY.size_for_width(500.0), 80.0);
        assert!(font::serif::FILES.iter().any(|(_, f)| *f == "InstrumentSerif-Regular.ttf"));
    }

    #[test]
    fn blending() {
        let b = LIGHT.foreground.over(LIGHT.background, 0.2);
        assert!(b.r > 200 && b.r < 210);
        assert_eq!(LIGHT.accent.rgba_hex(1.0), 0xC1272DFF);
        assert_eq!(LIGHT.accent.to_f32()[0], 193.0 / 255.0);
    }
}
